const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (msg._iamMode === 'off') {
    return [msg, null];
}
const negs = global.get('negotiations') || {};
const neg = Object.values(negs).find(n => n.agreementId === body.agreementId);
if (!neg) {
    msg.statusCode = 403;
    msg.payload = { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': 'agreement_not_found', 'dspace:reason': ['agreementId ' + body.agreementId + ' does not correspond to any negotiation'] };
    msg.headers = { 'Content-Type': 'application/json' };
    return [null, msg];
}
if (neg.state !== 'FINALIZED') {
    msg.statusCode = 403;
    msg.payload = { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': 'agreement_not_finalized', 'dspace:reason': ['negotiation ' + neg.id + ' is ' + neg.state + ', not FINALIZED'] };
    msg.headers = { 'Content-Type': 'application/json' };
    return [null, msg];
}
// Only reject on a *resolved* DID mismatch. In warn mode, unconfigured/failed
// verification leaves msg.identity null and must NOT block (tab contract: warn
// never blocks). In enforce mode this branch never sees a null identity anyway,
// since dsp-tx-iam-branch already routed iamRejected=true straight to the response.
if (msg._iamMode !== 'off' && msg.identity && msg.identity.did && neg.counterparty !== msg.identity.did) {
    msg.statusCode = 403;
    msg.payload = { '@context': 'https://w3id.org/dspace/2025/1/context.jsonld', '@type': 'dspace:Error', 'dspace:code': 'agreement_not_held_by_caller', 'dspace:reason': ['agreement ' + body.agreementId + ' is held by a different counterparty'] };
    msg.headers = { 'Content-Type': 'application/json' };
    return [null, msg];
}
return [msg, null];

// Outputs: [response, persist-trigger, metric-request, metric-completed, metric-error, kafka-provision]
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
if (!body.agreementId || !body.assetId) {
    msg.statusCode = 422;
    msg.payload = { detail: 'agreementId and assetId are required' };
    msg.headers = { 'Content-Type': 'application/json' };
    return [msg, null, null, null, null, null];
}
const format = body.format || 'http-pull';
if (format !== 'http-pull' && format !== 'kafka-streaming') {
    msg.statusCode = 422;
    msg.payload = { detail: 'format must be http-pull or kafka-streaming' };
    msg.headers = { 'Content-Type': 'application/json' };
    return [msg, null, null, null, null, null];
}

function isoUtcWithOffset(d) {
    // Python isoformat() on UTC-aware datetime emits microsecond precision
    // and `+00:00` suffix. JS toISOString() emits ms precision and `Z`. Pad
    // and swap to match exactly.
    return d.toISOString().slice(0, -1) + '000+00:00';
}

function provisionHttpPull(transfer, identity) {
    const secret = env.get('DSP_HMAC_SECRET');
    const baseUrl = (env.get('DSP_DATA_API_BASE_URL') || 'https://ai-insight.facis.cloud').replace(/\/$/, '');
    const ttl = Number(env.get('DSP_DEFAULT_TTL_SECONDS') || '3600');
    if (!secret) throw new Error('DSP_HMAC_SECRET unset');
    const path = '/api/data/' + transfer.assetId;
    const fromTs = (transfer.parameters && transfer.parameters.windowFrom) || '';
    const toTs = (transfer.parameters && transfer.parameters.windowTo) || '';
    const expiresAt = isoUtcWithOffset(new Date(Date.now() + ttl * 1000));
    const agreementId = transfer.agreementId || '';
    const rolesStr = (identity && identity.roles && identity.roles.length) ? [...identity.roles].sort().join(',') : '';
    // Percent-encode before concatenating into the canonical message (not just the URL):
    // encodeURIComponent never emits a raw ':', so the colon-delimited format stays
    // unambiguous no matter what characters agreementId/roles contain.
    const encodedAgreementId = encodeURIComponent(agreementId);
    const encodedRoles = encodeURIComponent(rolesStr);
    const message = 'GET:' + path + ':' + fromTs + ':' + toTs + ':' + expiresAt + ':' + encodedAgreementId + ':' + encodedRoles;
    const token = crypto.createHmac('sha256', Buffer.from(secret, 'utf8'))
                        .update(message, 'utf8').digest('hex');
    return {
        url: baseUrl + path + '?from=' + fromTs + '&to=' + toTs + '&expiresAt=' + expiresAt +
             '&agreementId=' + encodedAgreementId + '&roles=' + encodedRoles +
             '&token=' + token,
        token: token,
        expiresAt: expiresAt,
        bootstrap: null, topic: null, sasl: null
    };
}

function buildKafkaAccess(transfer) {
    // NF-3: honest access object. Real bootstrap, real (about-to-be-created)
    // topic, NO credential material — this cluster is mTLS-only by deliberate
    // decision (infrastructure/orce/init-deps-patch.yaml strips SASL from the
    // toolchain), and handing out this connector's own client key would let
    // the holder impersonate the connector on every topic it touches. mTLS
    // trust is arranged out-of-band; see accessNote.
    const bootstrap = env.get('DSP_KAFKA_BOOTSTRAP') || '212.132.83.222:9093';
    const ttl = Number(env.get('DSP_DEFAULT_TTL_SECONDS') || '3600');
    // Kafka topic names only allow [a-zA-Z0-9._-]; real assetIds like
    // 'dataset:facis:net-grid-hourly' contain ':' and must be sanitized.
    // (The old fabricated topic was never creatable on a real broker.)
    const safeAsset = transfer.assetId.replace(/[^a-zA-Z0-9._-]/g, '-');
    return {
        url: null, token: null,
        bootstrap: bootstrap,
        // transfer.id already carries the 'tp-' prefix. The inherited Python
        // code doubled it ('tp-tp-...'); fixed here (NF-3).
        topic: 'iot.dataset.' + safeAsset + '.' + transfer.id,
        sasl: null,
        accessNote: 'Connecting to this topic requires an mTLS client certificate trusted by the FACIS Kafka cluster, arranged out-of-band with the data space operator. This API does not deliver connection credentials.',
        // Advisory only — no reaper deletes the topic on expiry; the topic
        // lives until the transfer is terminated.
        expiresAt: isoUtcWithOffset(new Date(Date.now() + ttl * 1000))
    };
}

const now = isoUtcWithOffset(new Date());
const transferId = 'tp-' + crypto.randomBytes(6).toString('hex');
const transfer = {
    id: transferId,
    agreementId: body.agreementId,
    assetId: body.assetId,
    format: format,
    state: 'REQUESTED',
    access: null,
    reason: null,
    parameters: body.parameters || {},
    createdAt: now,
    updatedAt: now
};

const metricRequested = { payload: { family: 'facis_dsp_transfer_requests_total', label: format } };

if (format === 'kafka-streaming') {
    // NF-3: real provisioning. The transfer goes to STARTED here and STAYS
    // STARTED after the topic is created — a stream has no natural end, and
    // COMPLETED is terminal in the FSM matrix: parking a live stream there
    // made suspend/terminate unreachable (400) and would orphan its topic
    // forever. dsp-tx-kafka-admin owns the createTopic call, the final state
    // (access attached, or ERROR), the persist trigger, and the deferred
    // HTTP response (msg keeps req/res for exactly that reason).
    transfer.state = 'STARTED';
    transfer.updatedAt = isoUtcWithOffset(new Date());
    const transfers = flow.get('transfers') || {};
    transfers[transferId] = transfer;
    flow.set('transfers', transfers);
    msg._kafkaAction = 'create';
    msg._transferId = transferId;
    msg._kafkaAccess = buildKafkaAccess(transfer);
    node.log('Transfer ' + transferId + ' STARTED (kafka-streaming) — provisioning topic ' + msg._kafkaAccess.topic);
    return [null, null, metricRequested, null, null, msg];
}

// http-pull: unchanged synchronous auto-complete
// (REQUESTED → STARTED → COMPLETED, transfer_store.py:134-137 parity).
let metricCompleted = null;
let metricError = null;
try {
    transfer.state = 'STARTED';
    transfer.updatedAt = isoUtcWithOffset(new Date());
    const access = provisionHttpPull(transfer, msg.identity);
    transfer.state = 'COMPLETED';
    transfer.access = access;
    transfer.updatedAt = isoUtcWithOffset(new Date());
    metricCompleted = { payload: { family: 'facis_dsp_transfer_completions_total' } };
    node.log('Transfer ' + transferId + ' COMPLETED (http-pull)');
} catch (err) {
    transfer.state = 'ERROR';
    transfer.reason = String(err && err.message ? err.message : err);
    transfer.updatedAt = isoUtcWithOffset(new Date());
    metricError = { payload: { family: 'facis_dsp_transfer_errors_total' } };
    node.error('Transfer ' + transferId + ' ERROR: ' + transfer.reason);
}

const transfers = flow.get('transfers') || {};
transfers[transferId] = transfer;
flow.set('transfers', transfers);

msg.payload = { transferId: transferId };
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 202;
return [msg, { payload: '' }, metricRequested, metricCompleted, metricError, null];

const transfers = flow.get('transfers') || {};
const id = msg.req.params.id;
const found = transfers[id];
if (!found) {
    msg.statusCode = 404;
    msg.payload = { detail: 'Transfer ' + id + ' not found' };
} else {
    msg.statusCode = 200;
    msg.payload = found;
}
msg.headers = { 'Content-Type': 'application/json' };
return msg;

const transfers = flow.get('transfers') || {};
const all = Object.values(transfers);
let visible = all;
if (msg._iamMode === 'enforce' || msg._iamMode === 'warn') {
    const negs = global.get('negotiations') || {};
    const myDid = msg.identity && msg.identity.did;
    visible = all.filter(t => {
        const neg = Object.values(negs).find(n => n.agreementId === t.agreementId);
        return myDid && neg && neg.counterparty === myDid;
    });
}
msg.payload = visible;
msg.headers = { 'Content-Type': 'application/json' };
msg.statusCode = 200;
return msg;

const VALID = {
    REQUESTED: new Set(['STARTED','TERMINATED','ERROR']),
    STARTED:   new Set(['COMPLETED','SUSPENDED','TERMINATED','ERROR']),
    SUSPENDED: new Set(['STARTED','TERMINATED']),
    COMPLETED: new Set(),
    TERMINATED: new Set(),
    ERROR:     new Set()
};
const id = msg.req.params.id;
const transfers = flow.get('transfers') || {};
const cur = transfers[id];
if (!cur) {
    msg.statusCode = 404;
    msg.payload = { detail: 'Transfer ' + id + ' not found' };
    msg.headers = { 'Content-Type': 'application/json' };
    return [msg, null];
}
const target = 'SUSPENDED';
const allowed = VALID[cur.state] || new Set();
if (!allowed.has(target)) {
    msg.statusCode = 400;
    msg.payload = { detail: 'Invalid transition: ' + cur.state + ' \u2192 ' + target +
                            '. Valid targets: ' + (Array.from(allowed).join(',') || '(terminal)') };
    msg.headers = { 'Content-Type': 'application/json' };
    return [msg, null];
}
const now = new Date().toISOString().slice(0, -1) + '000+00:00';
const updated = Object.assign({}, cur, { state: target, reason: 'Suspended by consumer', updatedAt: now });
transfers[id] = updated;
flow.set('transfers', transfers);
msg.statusCode = 200;
msg.payload = updated;
msg.headers = { 'Content-Type': 'application/json' };
return [msg, { payload: '' }];

