// dsp-tx-kafka-admin — NF-3 (FR-DP-002): real Kafka topic create/delete via
// node-rdkafka's AdminClient, authenticating with the connector's OWN mTLS
// identity — the same certs every producer/consumer flow on this pod already
// uses (infrastructure/orce/kafka-certs-patch.yaml). No new credential is
// minted and none is ever delivered to callers (mTLS-only cluster; SASL is
// deliberately stripped from the build toolchain — init-deps-patch.yaml).
//
// Input msgs carry msg._kafkaAction:
//   'create' — from dsp-tx-create output 6, with msg._transferId,
//              msg._kafkaAccess, and the live req/res for the deferred
//              HTTP response.
//   'delete' — from dsp-tx-terminate output 3, fire-and-forget, with
//              msg._kafkaTopic only (no req/res).
// Outputs: [response, persist-trigger, metric-completed, metric-error]
//
// NOT harness-testable: needs node-rdkafka (native build) + a live broker.
// Covered by tests/e2e/dsp-kafka-transfer-e2e.js instead.
const action = msg._kafkaAction;
const conf = {
    'client.id': 'facis-dsp-connector-admin',
    'metadata.broker.list': env.get('DSP_KAFKA_BOOTSTRAP') || '212.132.83.222:9093',
    'security.protocol': 'ssl',
    'ssl.ca.location': '/etc/kafka-certs/ca.crt',
    'ssl.certificate.location': '/etc/kafka-certs/tls.crt',
    'ssl.key.location': '/etc/kafka-certs/tls.key',
    // Brokers are reached via bare IPs/NodePorts whose certs carry no
    // matching SANs — same setting as the kcat runbook and every other
    // FACIS Kafka client. Chain validation (mTLS) still applies.
    'ssl.endpoint.identification.algorithm': 'none'
};
const ERR = Kafka.CODES.ERRORS;

function adminOp(fn) {
    // AdminClient.create() connects synchronously and throws on failure
    // (verified against node-rdkafka v3.6.1 lib/admin.js).
    return new Promise((resolve, reject) => {
        let client;
        try { client = Kafka.AdminClient.create(conf); }
        catch (e) { reject(e); return; }
        fn(client, (err) => {
            try { client.disconnect(); } catch (e) { /* best-effort cleanup */ }
            if (err) reject(err); else resolve();
        });
    });
}

function nowIso() { return new Date().toISOString().slice(0, -1) + '000+00:00'; }

if (action === 'delete') {
    const topic = msg._kafkaTopic;
    (async () => {
        try {
            await adminOp((c, cb) => c.deleteTopic(topic, 10000, cb));
            node.log('dsp-tx-kafka-admin: deleted topic ' + topic);
        } catch (err) {
            if (err && err.code === ERR.ERR_UNKNOWN_TOPIC_OR_PART) {
                node.log('dsp-tx-kafka-admin: topic ' + topic + ' already gone');
            } else {
                // Non-fatal: the transfer is already TERMINATED and persisted
                // by dsp-tx-terminate. An orphaned topic is an ops cleanup
                // (kcat runbook), not a broken FSM.
                node.error('dsp-tx-kafka-admin: delete ' + topic + ' failed: ' + (err && err.message ? err.message : err));
            }
        }
    })();
    return null;
}

// action === 'create'
(async () => {
    const access = msg._kafkaAccess;
    const transferId = msg._transferId;
    const transfers = flow.get('transfers') || {};
    const transfer = transfers[transferId];
    if (!transfer) {
        msg.statusCode = 500;
        msg.payload = { detail: 'transfer ' + transferId + ' vanished before provisioning' };
        msg.headers = { 'Content-Type': 'application/json' };
        node.error('dsp-tx-kafka-admin: ' + msg.payload.detail);
        node.send([msg, null, null, null]);
        return;
    }
    let metricOk = null;
    let metricErr = null;
    try {
        await adminOp((c, cb) => c.createTopic({
            topic: access.topic,
            // ponytail: 1 partition / RF 1 — a per-transfer dataset stream
            // wants strict ordering and is demonstrator-scale. The shared
            // firehose topics use 3/1 (infrastructure-prerequisites.md §3.2);
            // bump num_partitions here if a single transfer ever needs
            // parallel consumption.
            num_partitions: 1,
            replication_factor: 1
        }, 10000, cb));
        transfer.access = access;
        transfer.updatedAt = nowIso();
        metricOk = { payload: { family: 'facis_dsp_transfer_completions_total' } };
        node.log('Transfer ' + transferId + ' provisioned: topic ' + access.topic + ' created');
    } catch (err) {
        if (err && err.code === ERR.ERR_TOPIC_ALREADY_EXISTS) {
            // Idempotent: transfer ids are random, but a retry/replay of the
            // same create can race. The topic being there IS success.
            transfer.access = access;
            transfer.updatedAt = nowIso();
            metricOk = { payload: { family: 'facis_dsp_transfer_completions_total' } };
            node.log('Transfer ' + transferId + ': topic ' + access.topic + ' already existed');
        } else {
            transfer.state = 'ERROR';
            transfer.reason = 'kafka topic provisioning failed: ' + (err && err.message ? err.message : err);
            transfer.updatedAt = nowIso();
            metricErr = { payload: { family: 'facis_dsp_transfer_errors_total' } };
            node.error('Transfer ' + transferId + ' ERROR: ' + transfer.reason);
        }
    }
    transfers[transferId] = transfer;
    flow.set('transfers', transfers);
    // 202 {transferId} regardless of outcome — parity with the old
    // auto-complete path, which also 202'd and surfaced ERROR via GET.
    // Worst-case client wait is the 10s AdminClient op timeout.
    msg.payload = { transferId: transferId };
    msg.headers = { 'Content-Type': 'application/json' };
    msg.statusCode = 202;
    node.send([msg, { payload: '' }, metricOk, metricErr]);
})();
return null;
